-- Read-only pre-check / post-check. Review ROW_MATCHES, identity and old quantity before any apply.
WITH targets (PERMIT_NUMBER,ACCOUNT_ID,EXPECTED_FLOCK_ID,NEW_EST_DISPOSAL,NEW_DISPOSAL_DATE,NEW_BIRDS_DISPOSED,SET_BIRDS) AS (
  SELECT * FROM VALUES
    ('30368','0FD02632-CDE6-E511-80E1-C4346BAC339C','03642A95-CC9A-F011-B4CC-000D3A13CD3A','2027-01-05'::DATE,NULL,NULL,FALSE),
    ('30371','CC48413D-CDE6-E511-80E1-C4346BAC339C','BE376333-D8AD-F011-BBD3-7C1E520D7E2C','2027-02-15'::DATE,NULL,NULL,FALSE),
    ('30372','3549413D-CDE6-E511-80E1-C4346BAC339C','71978F0C-D9AD-F011-BBD3-7C1E520D7E2C','2027-03-29'::DATE,NULL,NULL,FALSE),
    ('30374','F348413D-CDE6-E511-80E1-C4346BAC339C','409384C2-55BA-F011-BBD3-7C1E5214B9FF','2027-03-15'::DATE,NULL,NULL,FALSE),
    ('30375','38D02632-CDE6-E511-80E1-C4346BAC339C','D07191E2-55BA-F011-BBD3-7C1E5214B9FF','2027-03-22'::DATE,NULL,NULL,FALSE),
    ('40329','3549413D-CDE6-E511-80E1-C4346BAC339C','F1501FFB-5A2E-EF11-840B-7C1E520027C7','2025-12-22'::DATE,'2025-11-09'::DATE,73764,TRUE),
    ('40346','BD48413D-CDE6-E511-80E1-C4346BAC339C','3A298D5C-5BF0-EF11-BE20-00224827CF51','2026-07-16'::DATE,'2026-07-31'::DATE,15985,TRUE),
    ('40348','38D02632-CDE6-E511-80E1-C4346BAC339C','D15352E7-5BF0-EF11-BE20-00224827CF51','2026-07-27'::DATE,'2026-10-06'::DATE,48820,TRUE),
    ('40350','1BD02632-CDE6-E511-80E1-C4346BAC339C','69E63787-6C09-F011-BAE3-6045BDD8ED8F','2026-07-30'::DATE,'2026-09-03'::DATE,15356,TRUE),
    ('40357','5FD02632-CDE6-E511-80E1-C4346BAC339C','2D7B9F13-B83C-F011-B4CC-6045BDD8ED8F','2026-10-12'::DATE,'2026-09-24'::DATE,38108,TRUE),
    ('40358','CC48413D-CDE6-E511-80E1-C4346BAC339C','BAFD0A95-B93C-F011-B4CC-6045BDD8ED8F','2026-10-15'::DATE,'2026-09-24'::DATE,24052,TRUE),
    ('40366','5FD02632-CDE6-E511-80E1-C4346BAC339C','5CE3B3FE-3463-F011-BEC2-7C1E520D7E2C','2026-11-30'::DATE,'2026-09-24'::DATE,5196,TRUE),
    ('40369','83B14EF6-EA54-E711-8123-E0071B6AF2A1','320210BD-5D9D-F011-B41C-000D3A13CD3A','2026-11-30'::DATE,'2026-10-08'::DATE,1851,TRUE),
    ('40375','38D02632-CDE6-E511-80E1-C4346BAC339C','4EB139FD-55BA-F011-BBD3-7C1E5214B9FF','2027-03-22'::DATE,'2027-05-27'::DATE,NULL,FALSE)
)
SELECT t.*, f.FLOCK_ID, f.EST_DISPOSAL, f.DISPOSAL_DATE, f.BIRDS_DISPOSED, f.UPDATED_AT,
  COUNT(f.FLOCK_ID) OVER (PARTITION BY t.PERMIT_NUMBER,t.ACCOUNT_ID) AS ROW_MATCHES,
  EQUAL_NULL(f.FLOCK_ID,t.EXPECTED_FLOCK_ID) AS FLOCK_ID_MATCH,
  (EQUAL_NULL(f.EST_DISPOSAL,t.NEW_EST_DISPOSAL) AND EQUAL_NULL(f.DISPOSAL_DATE,t.NEW_DISPOSAL_DATE)
    AND (NOT t.SET_BIRDS OR EQUAL_NULL(f.BIRDS_DISPOSED,t.NEW_BIRDS_DISPOSED))) AS MATCHES_PROPOSED
FROM targets t LEFT JOIN EFNS_DEV.CORE.FLOCK f
  ON f.PERMIT_NUMBER=t.PERMIT_NUMBER AND f.ACCOUNT_ID=t.ACCOUNT_ID
ORDER BY t.PERMIT_NUMBER,f.FLOCK_ID;
